import{_ as t,a0 as o,w as r,s as f,ao as l,I as i,x as s,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 OfflineIMAP 同步郵件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 OfflineIMAP 同步郵件 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 OfflineIMAP 同步郵件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 OfflineIMAP 同步郵件 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200113 Keep your email in sync with OfflineIMAP","title":"使用 OfflineIMAP 同步郵件","tag":"202001","desc":""},"relativePath":"202001/20200113 Keep your email in sync with OfflineIMAP.md","filePath":"[post].md"}'),u={name:"202001/20200113 Keep your email in sync with OfflineIMAP.md"};function m(d,n,M,P,A,g){const a=o("Link");return r(),f("div",null,[n[20]||(n[20]=l('<h1 id="使用-offlineimap-同步郵件" tabindex="-1">使用 OfflineIMAP 同步郵件 <a class="header-anchor" href="#使用-offlineimap-同步郵件" aria-label="Permalink to “使用 OfflineIMAP 同步郵件”">​</a></h1><blockquote><p>將郵件鏡像保存到本地是整理消息的第一步。在我們的 20 個使用開源提升生產力的系列的第三篇文章中瞭解該如何做。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202001/20/235324nbgfyuwl98syowta.jpg" alt=""></p><p>去年，我在 19 天裏給你介紹了 19 個新（對你而言）的生產力工具。今年，我換了一種方式：使用你在使用或者還沒使用的工具，構建一個使你可以在新一年更加高效的環境。</p><h3 id="使用-offlineimap-在本地同步你的郵件" tabindex="-1">使用 OfflineIMAP 在本地同步你的郵件 <a class="header-anchor" href="#使用-offlineimap-在本地同步你的郵件" aria-label="Permalink to “使用 OfflineIMAP 在本地同步你的郵件”">​</a></h3><p>我與郵件之間存在愛恨交織的關係。我喜歡它讓我與世界各地的人交流的方式。但是，像你們中的許多人一樣，我收到過很多郵件，許多是來自郵件列表的，但也有很多垃圾郵件、廣告等。這些積累了很多。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_3-1.png" alt="The OfflineIMAP &quot;blinkenlights&quot; UI" title="The OfflineIMAP &quot;blinkenlights&quot; UI"></p>',7)),i("p",null,[n[2]||(n[2]=s("我嘗試過的大多數工具（除了大型郵件服務商外）都可以很好地處理大量郵件，它們都有一個共同點：它們都依賴於以 ",-1)),e(a,{href:"https://en.wikipedia.org/wiki/Maildir"},{default:p(()=>[...n[0]||(n[0]=[s("Maildir",-1)])]),_:1}),n[3]||(n[3]=s(" 格式存儲的本地郵件副本。這其中最有用的是 ",-1)),e(a,{href:"http://www.offlineimap.org/"},{default:p(()=>[...n[1]||(n[1]=[s("OfflineIMAP",-1)])]),_:1}),n[4]||(n[4]=s("。OfflineIMAP 是將 IMAP 郵箱鏡像到本地 Maildir 文件夾樹的 Python 腳本。我用它來創建郵件的本地副本並使其保持同步。大多數 Linux 發行版都包含它，並且可以通過 Python 的 pip 包管理器獲得。",-1))]),n[21]||(n[21]=l(`<p>示例的最小配置文件是一個很好的模板。首先將其複製到 <code>~/.offlineimaprc</code>。我的看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[general]</span></span>
<span class="line"><span>accounts = LocalSync</span></span>
<span class="line"><span>ui=Quiet</span></span>
<span class="line"><span>autorefresh=30</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Account LocalSync]</span></span>
<span class="line"><span>localrepository = LocalMail</span></span>
<span class="line"><span>remoterepository = MirrorIMAP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Repository MirrorIMAP]</span></span>
<span class="line"><span>type = IMAP</span></span>
<span class="line"><span>remotehost = my.mail.server</span></span>
<span class="line"><span>remoteuser = myusername</span></span>
<span class="line"><span>remotepass = mypassword</span></span>
<span class="line"><span>auth_mechanisms = LOGIN</span></span>
<span class="line"><span>createfolder = true</span></span>
<span class="line"><span>ssl = yes</span></span>
<span class="line"><span>sslcacertfile = OS-DEFAULT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Repository LocalMail]</span></span>
<span class="line"><span>type = Maildir</span></span>
<span class="line"><span>localfolders = ~/Maildir</span></span>
<span class="line"><span>sep = .</span></span>
<span class="line"><span>createfolder = true</span></span></code></pre></div><p>我的配置要做的是定義兩個倉庫：遠程 IMAP 服務器和本地 Maildir 文件夾。還有一個<strong>帳户</strong>，告訴 OfflineIMAP 運行時要同步什麼。你可以定義鏈接到不同倉庫的多個帳户。除了本地複製外，這還允許你從一台 IMAP 服務器複製到另一台作為備份。</p><p>如果你有很多郵件，那麼首次運行 OfflineIMAP 將花費一些時間。但是完成後，下次會花<em>少得多</em>的時間。你也可以將 OfflineIMAP 作為 cron 任務（我的偏好）或作為守護程序在倉庫之間不斷進行同步。其文檔涵蓋了所有這些內容以及 Gmail 等高級配置選項。</p><p>現在，我的郵件已在本地複製，並有多種工具用來加快搜索、歸檔和管理郵件的速度。這些我明天再説。</p><hr>`,6)),i("p",null,[n[6]||(n[6]=s("via: ",-1)),e(a,{href:"https://opensource.com/article/20/1/sync-email-offlineimap"},{default:p(()=>[...n[5]||(n[5]=[s("https://opensource.com/article/20/1/sync-email-offlineimap",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=s("作者：",-1)),e(a,{href:"https://opensource.com/users/ksonney"},{default:p(()=>[...n[7]||(n[7]=[s("Kevin Sonney",-1)])]),_:1}),n[12]||(n[12]=s(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...n[8]||(n[8]=[s("lujun9972",-1)])]),_:1}),n[13]||(n[13]=s(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:p(()=>[...n[9]||(n[9]=[s("geekpi",-1)])]),_:1}),n[14]||(n[14]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...n[10]||(n[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[n[17]||(n[17]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[15]||(n[15]=[s("LCTT",-1)])]),_:1}),n[18]||(n[18]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...n[16]||(n[16]=[s("Linux中國",-1)])]),_:1}),n[19]||(n[19]=s(" 榮譽推出",-1))])])}const h=t(u,[["render",m]]);export{T as __pageData,h as default};
